// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        amount = bound(amount, 1, 1000 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool depositOk, ) = address(c).call{value: amount}("");
        require(depositOk, "Deposit failed");

        uint256 contractBalanceBefore = address(c).balance;
        uint256 userBalanceBefore = c.balances(actor);

        vm.prank(actor);
        (bool withdrawOk, ) = address(c).call(abi.encodeWithSignature("withdraw()"));

        uint256 contractBalanceAfter = address(c).balance;
        uint256 userBalanceAfter = c.balances(actor);
        uint256 deducted = userBalanceBefore - userBalanceAfter;

        assertTrue(contractBalanceBefore - contractBalanceAfter == deducted);
    }
}
